<?php require_once 'config/config.php'; $pageTitle='Courses'; $q=trim($_GET['q']??''); $cat=(int)($_GET['category']??0); $categories=db()->query("SELECT * FROM course_categories ORDER BY name")->fetchAll(); $sql="SELECT c.*,a.name academy,cc.name category FROM courses c JOIN academies a ON a.id=c.academy_id JOIN course_categories cc ON cc.id=c.category_id WHERE 1"; $params=[]; if($q){$sql.=" AND (c.name LIKE ? OR a.name LIKE ? OR c.location LIKE ?)";$params=["%$q%","%$q%","%$q%"];} if($cat){$sql.=" AND c.category_id = ?";$params[]=$cat;} $sql.=" ORDER BY c.featured DESC,c.id DESC"; $st=db()->prepare($sql);$st->execute($params);$courses=$st->fetchAll(); require 'includes/header.php'; ?>
<section class="page-hero"><div class="container"><div class="eyebrow">Keep learning</div><h1>Find your next<br><span style="color:var(--teal)">chapter.</span></h1><p>Explore demo listings from Quetta academies. Filter by what you want to learn and where you want to learn it.</p></div></section><section class="section"><div class="container"><form class="filter-bar"><input class="input" name="q" value="<?=e($q)?>" placeholder="Search courses, academies, locations"><select class="select" name="category" style="max-width:220px"><option value="0">All categories</option><?php foreach($categories as $c): ?><option value="<?=$c['id']?>" <?=$cat==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach; ?></select><button class="btn btn-primary">Search</button></form><div class="section-heading"><div><div class="kicker"><?=count($courses)?> opportunities</div><h2>Popular courses</h2></div></div><div class="cards"><?php foreach($courses as $course): ?><article class="card"><img class="card-img" src="<?=image_url($course['image'])?>" alt="<?=e($course['name'])?>"><div class="card-body"><span class="pill"><?=e($course['category'])?></span><h3><?=e($course['name'])?></h3><p class="card-meta"><?=e($course['academy'])?> · <?=e($course['location'])?></p><p class="card-meta"><?=e($course['duration'])?></p><div style="display:flex;justify-content:space-between;align-items:center;margin-top:18px"><span class="price">PKR <?=number_format((float)$course['fee'])?></span><a class="kicker" href="contact.php?type=course&subject=<?=urlencode($course['name'])?>">Enquire →</a></div></div></article><?php endforeach; ?></div><?php if(!$courses): ?><div class="soft-panel"><h3>No courses found</h3><p>Try another search or category.</p></div><?php endif; ?></div></section>
<?php require 'includes/footer.php'; ?>